-- Task 14: install one approved core rule for every Task 11 threat category.
-- Rules are seeded disabled so deployment does not silently activate new detection policy.
-- Category availability is temporarily changed only inside this migration transaction and restored before commit.
LOCK TABLE threat_categories IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE task14_threat_category_state ON COMMIT DROP AS
  SELECT code, enabled, updated_at FROM threat_categories WHERE code IN ('BRUTE_FORCE', 'CREDENTIAL_ATTACK', 'PRIVILEGE_ESCALATION', 'SUSPICIOUS_ACCOUNT_ACTIVITY', 'UNAUTHORIZED_ACCESS', 'RECONNAISSANCE', 'SUSPICIOUS_NETWORK_ACTIVITY', 'PHISHING_SOCIAL_ENGINEERING', 'MALWARE', 'RANSOMWARE', 'DENIAL_OF_SERVICE', 'DATA_EXFILTRATION', 'WEB_APPLICATION_ATTACK', 'INSIDER_THREAT', 'SUPPLY_CHAIN_COMPROMISE');

UPDATE threat_categories SET enabled = true WHERE code IN ('BRUTE_FORCE', 'CREDENTIAL_ATTACK', 'PRIVILEGE_ESCALATION', 'SUSPICIOUS_ACCOUNT_ACTIVITY', 'UNAUTHORIZED_ACCESS', 'RECONNAISSANCE', 'SUSPICIOUS_NETWORK_ACTIVITY', 'PHISHING_SOCIAL_ENGINEERING', 'MALWARE', 'RANSOMWARE', 'DENIAL_OF_SERVICE', 'DATA_EXFILTRATION', 'WEB_APPLICATION_ATTACK', 'INSIDER_THREAT', 'SUPPLY_CHAIN_COMPROMISE');


SELECT r.id, m.id
FROM detection_rules r
JOIN mitre_mappings m ON m.technique_id = 'T1110'
WHERE r.name IN ('SX-CORE-001 Brute force authentication failures', 'SX-CORE-002 Credential attack indicators');

UPDATE threat_categories category
SET enabled = state.enabled, updated_at = state.updated_at
FROM task14_threat_category_state state
WHERE category.code = state.code;
